        ld d, a                 ;  5  D: dx
        call first              ; 18  HL: the byte of (x0, y0), C: its mask
        ld a, d                 ;  5
        cp e                    ;  5
        jp c, sr                ; 11  steeper than 45 degrees
fr:     ld b, d                 ;  5  flat: dx + 1 pixels
