        ex af, af'              ;  5
tsrpx:  ex af, af'              ;  5  the error,
        sub d                   ;  5  less dx: carry, below zero,
        ex af, af'              ;  5  kept with its carry
        ld a, c                 ;  5  the pixel
        or (hl)                 ;  8  into its byte, in the RAM
        ld (hl), a              ;  8
        ld a, l                 ;  5  and the byte to the VRAM:
        out (VDP_CTRL), a       ; 12  the write address
        ld a, h                 ;  5
        sub BUF_H - $40         ;  8  ... the RAM's page less BUF's, and $40
        out (VDP_CTRL), a       ; 12
        ld a, (hl)              ;  8
        out (VDP_DATA), a       ; 12
        inc l                   ;  5  a line down (chapter 22's down)
        ld a, l                 ;  5
        and 7                   ;  8
        jr nz, tsrsm            ; 13, or 8
        ld a, l                 ;  5
        sub 8                   ;  8
        ld l, a                 ;  5
        inc h                   ;  5
tsrsm:  ex af, af'              ;  5  the error, and its carry
        jr c, tsrdn             ; 13, or 8
        ex af, af'              ;  5
        djnz tsrpx              ; 14, or 9
        ret                     ; 11
tsrdn:  add a, e                ;  5  below zero: dy back,
        ex af, af'              ;  5
        rrc c                   ; 10  and a pixel right:
        jr nc, tsrnx            ; 13, or 8  in the same byte, or
        ld a, l                 ;  5  in the next, 8 on
        add a, 8                ;  8
        ld l, a                 ;  5
tsrnx:  djnz tsrpx              ; 14, or 9
        ret                     ; 11
tleft:  neg                     ; 10  to the left: dx = x0 - x1
        ld d, a                 ;  5  D: dx
        call tfirst             ; 18
        ld a, d                 ;  5
        cp e                    ;  5
        jp c, tsl               ; 11
tfl:    ld b, d                 ;  5  flat: dx + 1 pixels
        inc b                   ;  5
        srl a                   ; 10  the error: dx / 2
        ex af, af'              ;  5
tflpx:  ex af, af'              ;  5  the error,
        sub e                   ;  5  less dy: carry, below zero,
        ex af, af'              ;  5  kept with its carry
        ld a, c                 ;  5  the pixel
        or (hl)                 ;  8  into its byte, in the RAM
        ld (hl), a              ;  8
        ld a, l                 ;  5  and the byte to the VRAM:
        out (VDP_CTRL), a       ; 12  the write address
        ld a, h                 ;  5
        sub BUF_H - $40         ;  8  ... the RAM's page less BUF's, and $40
        out (VDP_CTRL), a       ; 12
        ld a, (hl)              ;  8
        out (VDP_DATA), a       ; 12
        rlc c                   ; 10  a pixel left:
        jr nc, tflsm            ; 13, or 8  in the same byte, or
        ld a, l                 ;  5  in the next, 8 back
        sub 8                   ;  8
        ld l, a                 ;  5
tflsm:  ex af, af'              ;  5  the error, and its carry
        jr c, tfldn             ; 13, or 8
        ex af, af'              ;  5
        djnz tflpx              ; 14, or 9
        ret                     ; 11
tfldn:  add a, d                ;  5  below zero: dx back,
        ex af, af'              ;  5
        inc l                   ;  5  and a line down (chapter 22's down)
        ld a, l                 ;  5
        and 7                   ;  8
        jr nz, tflnx            ; 13, or 8
        ld a, l                 ;  5
        sub 8                   ;  8
        ld l, a                 ;  5
        inc h                   ;  5
tflnx:  djnz tflpx              ; 14, or 9
        ret                     ; 11
tsl:    ld b, e                 ;  5  steep: dy + 1 pixels
        inc b                   ;  5
        ld a, e                 ;  5
        srl a                   ; 10  the error: dy / 2
        ex af, af'              ;  5
tslpx:  ex af, af'              ;  5  the error,
        sub d                   ;  5  less dx: carry, below zero,
        ex af, af'              ;  5  kept with its carry
        ld a, c                 ;  5  the pixel
        or (hl)                 ;  8  into its byte, in the RAM
        ld (hl), a              ;  8
        ld a, l                 ;  5  and the byte to the VRAM:
        out (VDP_CTRL), a       ; 12  the write address
        ld a, h                 ;  5
        sub BUF_H - $40         ;  8  ... the RAM's page less BUF's, and $40
        out (VDP_CTRL), a       ; 12
        ld a, (hl)              ;  8
        out (VDP_DATA), a       ; 12
        inc l                   ;  5  a line down (chapter 22's down)
        ld a, l                 ;  5
        and 7                   ;  8
        jr nz, tslsm            ; 13, or 8
        ld a, l                 ;  5
        sub 8                   ;  8
        ld l, a                 ;  5
        inc h                   ;  5
tslsm:  ex af, af'              ;  5  the error, and its carry
        jr c, tsldn             ; 13, or 8
        ex af, af'              ;  5
        djnz tslpx              ; 14, or 9
        ret                     ; 11
tsldn:  add a, e                ;  5  below zero: dy back,
        ex af, af'              ;  5
        rlc c                   ; 10  and a pixel left:
        jr nc, tslnx            ; 13, or 8  in the same byte, or
        ld a, l                 ;  5  in the next, 8 back
        sub 8                   ;  8
        ld l, a                 ;  5
tslnx:  djnz tslpx              ; 14, or 9
        ret                     ; 11

; tfirst: B = x, C = y -> HL: the byte of pixel (x, y), C: its mask
tfirst: call vaddr              ; 18
        ld a, h                 ;  5  in the buffer
        add a, BUF_H            ;  8
        ld h, a                 ;  5
        ld a, b                 ;  5
        and 7                   ;  8
        ld c, a                 ;  5
        ld b, high masks        ;  8
        ld a, (bc)              ;  8
        ld c, a                 ;  5
        ret                     ; 11

; clear: the 6,144 bytes of the buffer set to 0
clear:  ld hl, BUF              ; 11
        ld de, BUF + 1          ; 11
        ld bc, 6143             ; 11
        ld (hl), 0              ; 11
        ldir                    ; 23 a byte, 18 the last
        ret                     ; 11

; vaddr: B = x, C = y -> HL = the address of the byte that holds pixel (x, y),
; in the patterns of a Graphic II screen whose names run 0 to 255 in each
; third (chapter 22). Uses A.
vaddr:  ld a, c                 ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        and $1F                 ;  8: y / 8, the row of characters
        ld h, a                 ;  5
        ld a, b                 ;  5
        and $F8                 ;  8: the column of characters, x 8
        ld l, a                 ;  5
        ld a, c                 ;  5
        and 7                   ;  8: the line in the cell
        or l                    ;  5
        ld l, a                 ;  5
        ret                     ; 11

        ALIGN 256
masks:  db $80, $40, $20, $10, $08, $04, $02, $01 ; pixel n of a byte: bit 7 - n
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
